def slice_between(start_pat, end_pat, *, rstrip_nl=False):
    """取全文中第一个匹配 start_pat 的位置起、至第一个匹配 end_pat 的位置止（不含该位置）。"""
    s = re.search(start_pat, text)
    assert s, f"起点锚未命中：{start_pat}"
    e = re.search(end_pat, text[s.start() + 1:])
    assert e, f"终点锚未命中：{end_pat}"
    seg = text[s.start(): s.start() + 1 + e.start()]
    return seg.rstrip("\n") + "\n" if rstrip_nl else seg


def line_starting(prefix, expect=1):
    hits = [l for l in lines if l.startswith(prefix)]
    assert len(hits) == expect, f"锚 {prefix!r} 命中 {len(hits)} 行，期望 {expect}"
    return hits


